{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 전기차 충전 시 1시간 무료 후 할인 전 주차비 2,450원일 때 실제 납부 금액",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "「서울특별시 주차장 설치 및 관리 조례」 제7조제1항제9호에 따르면 전기자동차는 충전할 경우 1시간 범위 내에서 주차요금을 면제하고, 1시간 초과 시부터 부과되는 주차요금의 100분의 50을 할인합니다. 따라서 처음 1시간은 무료이고, 그 이후 부과되는 주차요금 2,450원의 100분의 50을 할인한 금액이 실제 납부 대상입니다. 같은 조 제2항에 따라 100원 미만의 단수는 계산하지 않으므로, 2,450원의 50%인 1,225원에서 100원 미만 단수 25원을 제외한 1,200원을 납부하게 됩니다.",
          "b_ids": "주차장:제7조제1항제9호, 주차장:제7조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
